# ── CloudWatch Log Group (main app) ──────────────────────────────────────────
resource "aws_cloudwatch_log_group" "main" {
  name              = "/${var.project_name}"
  retention_in_days = 30
  tags = { Name = "${var.project_name}-logs" }
}

resource "aws_cloudwatch_metric_alarm" "high_cpu" {
  alarm_name          = "${var.project_name}-high-cpu"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 2
  metric_name         = "CPUUtilization"
  namespace           = "AWS/ECS"
  period              = 60
  statistic           = "Average"
  threshold           = 80
  alarm_description   = "Alarm when CPUUtilization exceeds 80"
  treat_missing_data  = "notBreaching"

  dimensions = {
    ServiceName = "${var.project_name}"
  }
}

resource "aws_cloudwatch_metric_alarm" "high_errors" {
  alarm_name          = "${var.project_name}-high-errors"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 2
  metric_name         = "HTTPCode_Target_5XX_Count"
  namespace           = "AWS/ApplicationELB"
  period              = 60
  statistic           = "Average"
  threshold           = 10
  alarm_description   = "Alarm when HTTPCode_Target_5XX_Count exceeds 10"
  treat_missing_data  = "notBreaching"

  dimensions = {
    LoadBalancer = "${var.project_name}"
  }
}

